// returns W_res[k] and optc[k] for k=1..n using naive formula
void mergeNaive(const vector<ll>& sL,const vector<ll>& sR,ll SumA,ll p,int la,int lb, vector<ll>&W, vector<int>&optc){
    int n=la+lb;
    W.assign(n+1, NINF); optc.assign(n+1,-1);
    for(int k=1;k<=n;k++){
        ll best=NINF; int bc=-1;
        for(int c=0;c<=min(k,la);c++){
            ll a = getS(sL,c,la); if(a!=NINF&&a!=INF) a=p-a;
            else if(a==NINF) a=INF; else a=NINF;
            ll braw = getS(sR,k-c,lb);
            ll b;
            if(braw==NINF) b=INF; else if(braw==INF) b=NINF; else b=p-braw;
            // term = min(a, b - c*p + SumA)
            ll term;
            if(b==NINF) term=NINF;
            else term=min(a, b - (ll)c*p + SumA);
            // validity: term > wL[c+1]
            ll wlc1;
            ll raw=getS(sL,c+1,la);
            if(raw==NINF) wlc1=INF; else if(raw==INF) wlc1=NINF; else wlc1=p-raw;
            if(term==NINF) continue;
            if(!(term>wlc1)) continue;
            if(term>best){ best=term; bc=c; }
        }
        W[k]=best; optc[k]=bc;
    }
}
