#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF=LLONG_MAX/4;
const ll NINF=LLONG_MIN/4;

struct Node { vector<ll> s; ll sum; };
vector<Node> tr;
ll P;

void mergeInto(const vector<ll>&sL,const vector<ll>&sR,ll sumL,vector<ll>&out){
    int la=sL.size(), lb=sR.size();
    int n=la+lb;
    if(n==0){ out.clear(); return; }
    auto wLAt=[&](int c)->ll{ if(c<=0) return INF; if(c>la) return NINF; return P - sL[c-1]; };
    auto wRAt=[&](int m)->ll{ if(m<=0) return INF; if(m>lb) return NINF; return P - sR[m-1]; };
    auto termOf=[&](int c,int k)->ll{
        ll a=wLAt(c);
        ll b=wRAt(k-c);
        if(b==NINF) return NINF;
        ll term = min(a, b - (ll)c*P + sumL);
        ll c1=wLAt(c+1);
        if(!(term>c1)) return NINF;
        return term;
    };
    vector<ll> W(n+1,NINF);
    int prev=0;
    for(int k=1;k<=n;k++){
        int hi=min(k,la);
        int c=prev; if(c>hi) c=hi;
        ll best=termOf(c,k);
        while(c+1<=hi){
            ll t2=termOf(c+1,k);
            if(t2>=best){ c++; best=t2; }
            else break;
        }
        W[k]=best; prev=c;
    }
    out.resize(n);
    for(int k=1;k<=n;k++) out[k-1]=P - W[k];
}

// build over a[0..n-1]
void build(int id,int l,int r,const vector<ll>&a){
    if(l==r){ tr[id].sum=a[l]; tr[id].s.assign(1, P - a[l]); return; }
    int mid=(l+r)/2;
    build(id*2,l,mid,a);
    build(id*2+1,mid+1,r,a);
    tr[id].sum=tr[id*2].sum+tr[id*2+1].sum;
    mergeInto(tr[id*2].s, tr[id*2+1].s, tr[id*2].sum, tr[id].s);
}

ll processSeg(int id,ll x){
    ll cnt=upper_bound(tr[id].s.begin(),tr[id].s.end(),x)-tr[id].s.begin();
    return x + tr[id].sum - cnt*P;
}

void queryRec(int id,int l,int r,int ql,int qr,ll &x){
    if(ql<=l && r<=qr){ x=processSeg(id,x); return; }
    int mid=(l+r)/2;
    if(ql<=mid) queryRec(id*2,l,mid,ql,qr,x);
    if(qr>mid) queryRec(id*2+1,mid+1,r,ql,qr,x);
}

ll bruteAns(const vector<ll>&a,int l,int r,ll x,ll p){
    for(int i=l;i<=r;i++){ x+=a[i]; if(x>=p){x-=p;} }
    return x;
}

