    for(int tc=0;tc<20000;tc++){
        int n=rng()%10+1;
        P=rng()%12+1;
        vector<ll> a(n); for(auto&v:a) v=(ll)(rng()%31)-15;
        tr.assign(4*n+5, Node());
        build(1,0,n-1,a);
        for(int q=0;q<50;q++){
            int l=rng()%n, r2=rng()%n; if(l>r2) swap(l,r2);
            ll x=rng()%P; // x in [0,P)
            ll got; queryRec(1,0,n-1,l,r2,got=x);
            ll exp=bruteAns(a,l,r2,x,P);
